import json, sys, os
src, dst = sys.argv[1], sys.argv[2]
out = []
for line in open(src):
    try: d = json.loads(line)
    except Exception: continue
    t = d.get('type')
    ts = (d.get('timestamp') or '')[11:19]
    if t == 'user' and not d.get('isMeta'):
        c = d.get('message', {}).get('content')
        if isinstance(c, str):
            out.append(f"\n##### USER {ts}\n{c.strip()}\n")
        elif isinstance(c, list):
            for x in c:
                if isinstance(x, dict) and x.get('type') == 'text':
                    out.append(f"\n##### USER {ts}\n{x['text'].strip()}\n")
                elif isinstance(x, dict) and x.get('type') == 'tool_result':
                    cc = x.get('content')
                    s = cc if isinstance(cc, str) else ' '.join(y.get('text','') for y in (cc or []) if isinstance(y, dict))
                    s = s.strip().replace('\n', ' | ')
                    out.append(f"   [result] {s[:300]}")
    elif t == 'assistant':
        for x in d.get('message', {}).get('content', []) or []:
            if not isinstance(x, dict): continue
            if x.get('type') == 'text' and x['text'].strip():
                out.append(f"\n----- ASSISTANT {ts}\n{x['text'].strip()}\n")
            elif x.get('type') == 'tool_use':
                inp = x.get('input', {})
                s = inp.get('command') or inp.get('file_path') or inp.get('description') or inp.get('prompt') or json.dumps(inp)[:200]
                s = str(s).replace('\n', ' ⏎ ')
                out.append(f"   [tool {x.get('name')}] {s[:400]}")
open(dst, 'w').write('\n'.join(out))
print(dst, os.path.getsize(dst))
EOF
